(7319194, 1142108, 30049, '<td valign="top">Lovely image.  My top pick for this challenge.  Love the tones you''ve used for this.  Nice patience in waiting for that "right" moment of bird with fisherman action as well.</td>', 'Lovely image.  My top pick for this challenge.  Love the tones you''ve used for this.  Nice patience in waiting for that "right" moment of bird with fisherman action as well.', '2015-02-21 11:37:23.000000', NULL, 1),
(7319196, 1142132, 30049, '<td valign="top">This is a fun and intriguing image, with or without a "duotone" theme.  Nicely done!  One of my top picks.  Good luck. BTW - I voted several days ago ...</td>', 'This is a fun and intriguing image, with or without a "duotone" theme.  Nicely done!  One of my top picks.  Good luck. BTW - I voted several days ago ...', '2015-02-21 11:39:30.000000', NULL, 1),
