(7320082, 1142218, 156466, '<td valign="top">I would love this more than the 8 I gave it there was enough definition in the face of the forward person.  This is likely a non-issue without the auto-squash of vertical images here, but ...</td>', 'I would love this more than the 8 I gave it there was enough definition in the face of the forward person.  This is likely a non-issue without the auto-squash of vertical images here, but ...', '2015-02-22 17:21:31.000000', NULL, 1),
(7320083, 1141564, 156466, '<td valign="top">Whoever you are, please stop letterboxing your work.  It doesn''t need it outside of Instagram.  Lovely photo, but I hate the box.</td>', 'Whoever you are, please stop letterboxing your work.  It doesn''t need it outside of Instagram.  Lovely photo, but I hate the box.', '2015-02-22 17:22:16.000000', NULL, 1),
