(7320100, 1142208, 156466, '<td valign="top">I want this bigger or more tightly cropped, but I suspect that if this was a horizontal shot I wouldn''t be saying it.</td>', 'I want this bigger or more tightly cropped, but I suspect that if this was a horizontal shot I wouldn''t be saying it.', '2015-02-22 17:44:52.000000', NULL, 1),
(7320101, 1141973, 156466, '<td valign="top">I wouldn''t have appreciated the treatment here as much, I suspect, had it not been for the treatment of a similar portrait that I saw just before this. Duotone can be easily overdone from a contrast standpoint.  Kudos for not going there.  Lovely.</td>', 'I wouldn''t have appreciated the treatment here as much, I suspect, had it not been for the treatment of a similar portrait that I saw just before this. Duotone can be easily overdone from a contrast standpoint.  Kudos for not going there.  Lovely.', '2015-02-22 17:48:19.000000', NULL, 1),
(7320102, 1141750, 156466, '<td valign="top">I somehow wish it was the gentleman who was in focus and not the menu.  Still, nicely done.</td>', 'I somehow wish it was the gentleman who was in focus and not the menu.  Still, nicely done.', '2015-02-22 17:49:05.000000', NULL, 1),
(7320103, 1142112, 156466, '<td valign="top">Love the idea, and have tried and failed many times.  You wound up where I normally do.</td>', 'Love the idea, and have tried and failed many times.  You wound up where I normally do.', '2015-02-22 17:50:15.000000', NULL, 1),
